    print('카드를 사용해라')
else:
    print('걸어가라')

# 클래스 및 상속, 오버라이딩 예제
class Calculator:
    def __init__(self, val=0):
        self.value = val
    def add(self, val):
        self.value += val

class UpgradeCalculator(Calculator):
    def minus(self, val):  # 새로운 기능 추가
        self.value -= val

cal = UpgradeCalculator(100)
cal.add(20)
cal.minus(50)
print(cal.value)  # 70

