# 2. 게시판 페이징 예제
def get_total_page(m, n):
    if m % n == 0:
        return m // n
    else:
        return m // n + 1

# 4. 특정 디렉토리 파일 검색 예제
import os

def search_dir(dirname):
    try:
        filenames = os.listdir(dirname)
        for filename in filenames:
            full_path = os.path.join(dirname, filename)
            if os.path.isdir(full_path):
                search_dir(full_path)
            else:
                ext = os.path.splitext(full_path)[-1]
                if ext == '.py':
                    print(full_path)
    except PermissionError:
        pass

# 실행 시간을 측정하는 데코레이터 예제
import time

def elapsed(original_fn):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = original_fn(*args, **kwargs)
        end = time.time()
        print(f'실행 시간: {end - start:.4f}초')
        return result
    return wrapper

@elapsed
def my_heavy_task():
    time.sleep(1)

# 제너레이터를 활용한 피보나치 수열 예제
def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

for fib in fibonacci(5):
    print(fib)  # 0 1 1 2 3 출력
